32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The closed set of insurable item types, each with its base premium in gold. */
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	} as const satisfies Record<string, number>;
54	
55	export type ItemType = keyof typeof BASE_PREMIUMS;
56	
57	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	
62	const groupByType = (items: Item[]): Item[][] => {
63	  const groups = new Map<string, Item[]>();
64	  for (const item of items) {
65	    const group = groups.get(item.type) ?? [];
66	    group.push(item);
67	    groups.set(item.type, group);
68	  }
69	  return [...groups.values()];
70	};
71	
72	/** Three alike components form a block, priced at a special base premium. */
73	const groupBasePremium = (group: Item[]): number =>
74	  group.length === BLOCK_SIZE
75	    ? BLOCK_BASE_PREMIUM
76	    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);
77	
78	const blockAwareBasePremium = (items: Item[]): number =>
79	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
80	
81	const quotePremium = (items: Item[]): number => {
82	  const basePremium = blockAwareBasePremium(items);
83	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
84	  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
85	};
86	
87	const runStep = (step: Step): Result => {
88	  if (step.op === "quote") return { premium: quotePremium(step.items) };
89	  throw new Error(`Unsupported step: ${step.op}`);
90	};
91	
92	export const runScenario = (scenario: Scenario): { results: Result[] } => {
93	  return { results: scenario.steps.map(runStep) };
94	};
